    const fact = new Array(max).fill(1n);
    const inv_fact = new Array(max).fill(1n);

    for (let i = 1n; i < max; i++) {
        fact[i] = fact[i - 1n] * i % BigInt(mod);
    }

    inv_fact[max - 1] = modPow(fact[max - 1], BigInt(mod - 2), BigInt(mod));
    for (let i = max - 2; i >= 0; i--) {
        inv_fact[i] = inv_fact[i + 1n] * BigInt(i + 1) % BigInt(mod);
    }

    function comb(n, k) {
        if (n < 0 || k < 0 || n < k) return 0n;
        return fact[n] * inv_fact[k] % BigInt(mod) * inv_fact[n - k] % BigInt(mod);
    }

